// Package pplxdecider implements Perplexity's decision checkpoint on its
// Qwen3_5Model backbone.
package pplxdecider

import (
	"fmt"
	"math"
	"slices"

	"github.com/ollama/ollama/mlx"
	"github.com/ollama/ollama/mlxrunner/batch"
	"github.com/ollama/ollama/mlxrunner/cache"
	"github.com/ollama/ollama/mlxrunner/model"
	"github.com/ollama/ollama/mlxrunner/model/qwen3_5"
	"github.com/ollama/ollama/mlxrunner/nn"
)

type config struct {
	FormatVersion int      `json:"format_version"`
	Codes         []string `json:"codes"`
	TokenIDs      []int32  `json:"token_ids"`
	Temperature   float32  `json:"temperature"`
	MaxPixels     int32    `json:"max_pixels"`
	AttentionMode string   `json:"attention_mode"`
	Pooling       string   `json:"pooling"`
}

type jointConfig struct {
	Version       int    `json:"version"`
	Template      string `json:"template"`
	Marker        string `json:"marker"`
	ReadoutOffset int    `json:"readout_offset"`
}

type Model struct {
	*qwen3_5.Model
	Readout  *nn.Linear
	config   config
	markerID int32
}

func init() { model.Register("Qwen3_5Model", newModel) }

func newModel(root *model.Root) (model.Model, error) {
	var cfg config
	if err := root.Manifest.ReadConfigJSON("decision_config.json", &cfg); err != nil {
		return nil, fmt.Errorf("read Perplexity decision config: %w", err)
	}
	var joint jointConfig
	if err := root.Manifest.ReadConfigJSON("joint_config.json", &joint); err != nil {
		return nil, fmt.Errorf("read Perplexity joint config: %w", err)
	}
	if joint.Version != 3 || joint.Template != "joint-question-inline-readout-v1" || joint.Marker != "<|fim_suffix|>" || joint.ReadoutOffset != 0 {
		return nil, fmt.Errorf("unsupported Perplexity joint protocol")
	}
	if cfg.FormatVersion != 2 || len(cfg.Codes) != 255 || len(cfg.TokenIDs) != len(cfg.Codes) {
		return nil, fmt.Errorf("invalid Perplexity decision vocabulary or format")
	}
	if cfg.Temperature <= 0 || math.IsNaN(float64(cfg.Temperature)) || math.IsInf(float64(cfg.Temperature), 0) {
		return nil, fmt.Errorf("invalid Perplexity temperature %g", cfg.Temperature)
	}
	if cfg.Pooling != "last" {
		return nil, fmt.Errorf("unsupported Perplexity pooling %q", cfg.Pooling)
	}
	if cfg.AttentionMode != "noncausal_full_attention" {
		return nil, fmt.Errorf("unsupported Perplexity attention mode %q", cfg.AttentionMode)
	}
	backbone, err := qwen3_5.NewModel(root)
	if err != nil {
		return nil, err
	}
	m := &Model{Model: backbone.(*qwen3_5.Model), config: cfg}
	m.Config.NoncausalFullAttention = true
	// Match the publisher's FP32 recurrent decay over long decision rows.
	m.Config.PreciseGatedDeltaDecay = true
	if cfg.MaxPixels <= 0 {
		return nil, fmt.Errorf("invalid Perplexity image limit %d", cfg.MaxPixels)
	}
	m.VisionMaxPixels = cfg.MaxPixels
	if m.Config.ModelType != "qwen3_5_text" {
		return nil, fmt.Errorf("unsupported Perplexity backbone %q", m.Config.ModelType)
	}
	seen := make(map[int32]bool, len(cfg.TokenIDs))
	for i, code := range cfg.Codes {
		id := cfg.TokenIDs[i]
		if id < 0 || id >= m.Config.VocabSize || seen[id] || !slices.Equal(m.Tokenizer().Encode(code, false), []int32{id}) {
			return nil, fmt.Errorf("invalid Perplexity answer code %q at row %d", code, i)
		}
		seen[id] = true
	}
	markerIDs := m.Tokenizer().Encode(joint.Marker, false)
	if len(markerIDs) != 1 {
		return nil, fmt.Errorf("Perplexity readout marker must be one token")
	}
	var ok bool
	if m.markerID, ok = m.Tokenizer().GetSpecialToken(joint.Marker); !ok || m.markerID != markerIDs[0] {
		return nil, fmt.Errorf("Perplexity readout marker is not a special token")
	}
	return m, nil
}

// A full-attention layer reads later tokens in the decision row. A prefix
// snapshot cannot represent the row after its question or state changes.
func (m *Model) NewCaches() []cache.Cache { return nil }

func (m *Model) Forward(b *batch.Batch, _ []cache.Cache) (*mlx.Array, *mlx.Array) {
	return m.Model.Forward(b, nil)
}

func (m *Model) LoadWeights(tensors map[string]*mlx.Array) error {
	if err := m.Model.LoadWeights(tensors); err != nil {
		return err
	}
	w := tensors["weight"] // The publisher keeps its readout in readout.safetensors.
	if w == nil || w.DType() != mlx.DTypeBFloat16 || !slices.Equal(w.Dims(), []int{255, int(m.Config.HiddenSize)}) {
		return fmt.Errorf("Perplexity requires a BF16 readout weight of shape [255,%d]", m.Config.HiddenSize)
	}
	m.Readout = &nn.Linear{Weight: w}
	return nil
}

package pplxdecider

import (
	"context"
	"fmt"
	"net/http"
	"regexp"
	"strings"

	"github.com/ollama/ollama/api"
	"github.com/ollama/ollama/llm"
	"github.com/ollama/ollama/mlx"
	"github.com/ollama/ollama/mlxrunner/batch"
	"github.com/ollama/ollama/mlxrunner/model"
	"github.com/ollama/ollama/model/renderers"
)

var _ llm.Scorer = (*Model)(nil)

const (
	imageMarker   = "<|vision_start|><|image_pad|><|vision_end|>"
	readoutMarker = "<|fim_suffix|>"
)

var specialTokenPattern = regexp.MustCompile(`<\|[^<>]+\|>|<tts_[a-z_]+>`)

// User text must not introduce a readout or chat control token.
func escapeDecisionText(value string) string {
	return specialTokenPattern.ReplaceAllStringFunc(value, func(token string) string {
		return "＜" + token[1:len(token)-1] + "＞"
	})
}

func (m *Model) scorePrompt(input llm.ScoreRequest, rows []llm.ScoreRow) (string, int, error) {
	var body strings.Builder
	for range input.Images {
		body.WriteString(imageMarker)
	}
	body.WriteString("State:\n")
	body.WriteString(escapeDecisionText(input.State))
	for i, row := range rows {
		if row.Question == nil || len(row.Question.Options) < 1 || len(row.Question.Options) > len(m.config.Codes) {
			return "", 0, fmt.Errorf("question %d has an invalid option count", i)
		}
		body.WriteString("\n\nQuestion ")
		fmt.Fprintf(&body, "%d:\n", i)
		body.WriteString(escapeDecisionText(row.Question.Instructions))
		body.WriteString("\nOptions:\n")
		for j, option := range row.Question.Options {
			if j > 0 {
				body.WriteByte('\n')
			}
			fmt.Fprintf(&body, "%s: %s", m.config.Codes[j], escapeDecisionText(option))
		}
		body.WriteByte('\n')
		body.WriteString(readoutMarker)
	}
	userBody := body.String()
	prompt, err := renderers.RenderWithRenderer("qwen3.8", []api.Message{
		{Role: "system", Content: input.System},
		{Role: "user", Content: userBody},
	}, nil, &api.ThinkValue{Value: false})
	if err != nil {
		return "", 0, err
	}
	start := strings.LastIndex(prompt, userBody)
	if start < 0 {
		return "", 0, fmt.Errorf("rendered Perplexity prompt lost its user message")
	}
	return prompt, start, nil
}

func (m *Model) prepareJoint(input llm.ScoreRequest, rows []llm.ScoreRow) (*model.PreparedRequest, []int32, error) {
	prompt, imageStart, err := m.scorePrompt(input, rows)
	if err != nil {
		return nil, nil, err
	}
	var prepared *model.PreparedRequest
	if len(input.Images) == 0 {
		prepared, err = m.PrepareMedia([]model.Segment{{Tokens: m.Tokenizer().Encode(prompt, false)}})
	} else {
		var segments []model.Segment
		start := 0
		for i, image := range input.Images {
			end := imageStart + i*len(imageMarker)
			if !strings.HasPrefix(prompt[end:], imageMarker) {
				return nil, nil, fmt.Errorf("image %d is missing from the rendered prompt", i)
			}
			segments = append(segments, model.Segment{Tokens: m.Tokenizer().Encode(prompt[start:end], false)})
			segments = append(segments, model.Segment{Kind: "image", Data: image})
			start = end + len(imageMarker)
		}
		segments = append(segments, model.Segment{Tokens: m.Tokenizer().Encode(prompt[start:], false)})
		prepared, err = m.PrepareMedia(segments)
	}
	if err != nil {
		return nil, nil, err
	}
	var markers []int32
	for i, token := range prepared.Tokens {
		if token == m.markerID {
			markers = append(markers, int32(i))
		}
	}
	if len(markers) != len(rows) {
		return nil, nil, fmt.Errorf("Perplexity readout markers do not match questions")
	}
	return prepared, markers, nil
}

type scoreChunk struct {
	rows     []llm.ScoreRow
	prepared *model.PreparedRequest
	markers  []int32
}

// A request shares one noncausal sequence. Split only when its complete
// sequence exceeds the context limit, keeping the state and images in each part.
func (m *Model) planScore(input llm.ScoreRequest) ([]scoreChunk, error) {
	var chunks []scoreChunk
	var split func([]llm.ScoreRow) error
	split = func(rows []llm.ScoreRow) error {
		prepared, markers, err := m.prepareJoint(input, rows)
		if err != nil {
			return err
		}
		if len(prepared.Tokens) <= input.MaxTokens {
			chunks = append(chunks, scoreChunk{rows: rows, prepared: prepared, markers: markers})
			return nil
		}
		if len(rows) == 1 {
			return fmt.Errorf("question needs %d tokens with state and images; limit is %d", len(prepared.Tokens), input.MaxTokens)
		}
		middle := len(rows) / 2
		if err := split(rows[:middle]); err != nil {
			return err
		}
		return split(rows[middle:])
	}
	if err := split(input.Rows); err != nil {
		return nil, err
	}
	return chunks, nil
}

func (m *Model) Score(ctx context.Context, input llm.ScoreRequest) (llm.ScoreResponse, error) {
	var result llm.ScoreResponse
	cached := 0
	result.CachedTokens = &cached
	badRequest := func(err error) (llm.ScoreResponse, error) {
		return result, api.StatusError{StatusCode: http.StatusBadRequest, ErrorMessage: err.Error()}
	}
	if input.System == "" || len(input.Rows) < 1 || len(input.Rows) > 64 || input.MaxTokens < 1 || input.MaxTokens > m.MaxContextLength() {
		return badRequest(fmt.Errorf("invalid Perplexity system prompt, question count, or context limit"))
	}
	if err := ctx.Err(); err != nil {
		return result, err
	}
	chunks, err := m.planScore(input)
	if err != nil {
		return badRequest(err)
	}
	for _, chunk := range chunks {
		if err := ctx.Err(); err != nil {
			return result, err
		}
		var logits []float32
		mlx.Scoped(func() {
			prepared := chunk.prepared
			media := make([]batch.MediaItem, len(prepared.Items))
			for i := range prepared.Items {
				item := &prepared.Items[i]
				data := mlx.FromValues(item.MediaData, item.Dims...)
				media[i] = batch.MediaItem{Pos: item.Range[0], Opaque: item.Opaque, Features: m.EncodeMedia(item, data)}
				item.MediaData = nil
			}
			b := &batch.Batch{
				InputIDs:     mlx.FromValues(prepared.Tokens, 1, len(prepared.Tokens)),
				SeqOffsets:   []int32{0},
				SeqQueryLens: []int32{int32(len(prepared.Tokens))},
				Media:        media,
			}
			if prepared.Layout != nil {
				b.Layout = []any{prepared.Layout}
			}
			hidden, _ := m.Forward(b, nil)
			readouts := hidden.TakeAxis(mlx.FromValues(chunk.markers, len(chunk.markers)), 1)
			output := mlx.DivScalar(m.Readout.Forward(readouts).AsType(mlx.DTypeFloat32), m.config.Temperature)
			output = output.Reshape(len(chunk.rows) * len(m.config.Codes))
			mlx.Eval(output)
			logits = output.Floats()
		})
		for i, row := range chunk.rows {
			start := i * len(m.config.Codes)
			count := len(row.Question.Options)
			result.Logits = append(result.Logits, logits[start:start+count])
		}
		result.InputTokens += len(chunk.prepared.Tokens)
	}
	return result, ctx.Err()
}

package server

import (
	"context"
	"strings"
	"testing"
	"time"
)

func TestGetAuthorizationTokenRejectsCrossDomain(t *testing.T) {
	tests := []struct {
		realm        string
		originalHost string
		wantMismatch bool
	}{
		{"https://example.com/token", "example.com", false},
		{"https://example.com/token", "other.com", true},
		{"https://example.com/token", "localhost:8000", true},
		{"https://localhost:5000/token", "localhost:5000", false},
		{"https://localhost:5000/token", "localhost:6000", true},
	}

	for _, tt := range tests {
		t.Run(tt.originalHost, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
			defer cancel()

			challenge := registryChallenge{Realm: tt.realm, Service: "test", Scope: "repo:x:pull"}
			_, err := getAuthorizationToken(ctx, challenge, tt.originalHost)

			isMismatch := err != nil && strings.Contains(err.Error(), "does not match")
			if tt.wantMismatch && !isMismatch {
				t.Errorf("expected domain mismatch error, got: %v", err)
			}
			if !tt.wantMismatch && isMismatch {
				t.Errorf("unexpected domain mismatch error: %v", err)
			}
		})
	}
}

func TestParseRegistryChallenge(t *testing.T) {
	tests := []struct {
		input                             string
		wantRealm, wantService, wantScope string
	}{
		{
			`Bearer realm="https://auth.example.com/token",service="registry",scope="repo:foo:pull"`,
			"https://auth.example.com/token", "registry", "repo:foo:pull",
		},
		{
			`Bearer realm="https://r.ollama.ai/v2/token",service="ollama",scope="-"`,
			"https://r.ollama.ai/v2/token", "ollama", "-",
		},
		{"", "", "", ""},
	}

	for _, tt := range tests {
		result := parseRegistryChallenge(tt.input)
		if result.Realm != tt.wantRealm || result.Service != tt.wantService || result.Scope != tt.wantScope {
			t.Errorf("parseRegistryChallenge(%q) = {%q, %q, %q}, want {%q, %q, %q}",
				tt.input, result.Realm, result.Service, result.Scope,
				tt.wantRealm, tt.wantService, tt.wantScope)
		}
	}
}

func TestRegistryChallengeURL(t *testing.T) {
	challenge := registryChallenge{
		Realm:   "https://auth.example.com/token",
		Service: "registry",
		Scope:   "repo:foo:pull repo:bar:push",
	}

	u, err := challenge.URL()
	if err != nil {
		t.Fatalf("URL() error: %v", err)
	}

	if u.Host != "auth.example.com" {
		t.Errorf("host = %q, want %q", u.Host, "auth.example.com")
	}
	if u.Path != "/token" {
		t.Errorf("path = %q, want %q", u.Path, "/token")
	}

	q := u.Query()
	if q.Get("service") != "registry" {
		t.Errorf("service = %q, want %q", q.Get("service"), "registry")
	}
	if scopes := q["scope"]; len(scopes) != 2 {
		t.Errorf("scope count = %d, want 2", len(scopes))
	}
	if q.Get("ts") == "" {
		t.Error("missing ts")
	}
	if q.Get("nonce") == "" {
		t.Error("missing nonce")
	}

	// Nonces should differ between calls
	u2, _ := challenge.URL()
	if q.Get("nonce") == u2.Query().Get("nonce") {
		t.Error("nonce should be unique per call")
	}
}

func TestRegistryChallengeURLInvalid(t *testing.T) {
	challenge := registryChallenge{Realm: "://invalid"}
	if _, err := challenge.URL(); err == nil {
		t.Error("expected error for invalid URL")
	}
}

